/** Card identity and filters only. Prices are supplied by Pokechain's contracts. */
export interface CardIdentity {
  title: string;
  image: string;
  grader: string;
}

/** The ERC-721 metadata is generated by SlabVault itself; no external URL is fetched. */
export function cardFromTokenURI(uri: string): CardIdentity & { certNumber: string } {
  const prefix = "data:application/json;base64,";
  if (!uri.startsWith(prefix)) throw new Error("Expected Pokechain's on-chain card metadata");
  const bytes = Uint8Array.from(atob(uri.slice(prefix.length)), (c) => c.charCodeAt(0));
  const data = JSON.parse(new TextDecoder().decode(bytes));
  if (typeof data.name !== "string" || typeof data.image !== "string" || !Array.isArray(data.attributes)) {
    throw new Error("Incomplete on-chain card metadata");
  }
  const attribute = (name: string): string => {
    const value = data.attributes.find((a: { trait_type?: string }) => a.trait_type === name)?.value;
    if (typeof value !== "string") throw new Error(`Missing card attribute: ${name}`);
    return value;
  };
  return { title: data.name, image: data.image, grader: attribute("Grader"), certNumber: attribute("Cert number") };
}

function imageCardId(image: string): string | null {
  try {
    const url = new URL(image);
    if (url.hostname !== "images.pokemontcg.io") return null;
    const match = url.pathname.match(/^\/([^/]+)\/([^/]+?)(?:_hires)?\.(?:png|jpg)$/i);
    return match ? `${match[1]}/${match[2]}`.toLowerCase() : null;
  } catch {
    return null;
  }
}

function printedCard(title: string): string | null {
  const text = title.normalize("NFKD").replace(/[\u0300-\u036f]/g, "");
  // Require a set, year and collector number; a shared Pokemon name is insufficient.
  if (!/^\d{4}\s+Pokemon\s+.+#\S+\s+\S/i.test(text)) return null;
  return text.replace(/\s*\((?:PSA|BGS|CGC|SGC)\s+[^)]*\)\s*$/i, "").toLowerCase().replace(/\s+/g, " ").trim();
}

export function sameCard(a: CardIdentity, b: CardIdentity): boolean {
  const aId = imageCardId(a.image);
  const bId = imageCardId(b.image);
  if (aId && bId) return aId === bId;
  const aTitle = printedCard(a.title);
  return aTitle !== null && aTitle === printedCard(b.title);
}

export function cardGrade(card: CardIdentity): number | null {
  const match = card.title.match(/\((?:PSA|BGS|CGC|SGC)\s+(\d+(?:\.\d+)?)/i);
  return match ? Number(match[1]) : null;
}

export type GradeFilter = "all" | "same" | "nearby";

export function matchesComparable(target: CardIdentity, candidate: CardIdentity, grader = "all", grade: GradeFilter = "all"): boolean {
  if (!sameCard(target, candidate)) return false;
  if (grader !== "all" && candidate.grader.toUpperCase() !== grader.toUpperCase()) return false;
  if (grade === "all") return true;
  const base = cardGrade(target);
  const other = cardGrade(candidate);
  return base !== null && other !== null && Math.abs(base - other) <= (grade === "same" ? 0 : 1);
}
